/**
 * 性能测试函数
 * @param {GPUDevice} device - WebGPU设备
 * @param {GuidedFilterParams} params - 算法参数
 * @param {number[][]} resolutions - 测试分辨率列表
 * @returns {Promise<Object>} 性能测试结果
 */
export async function benchmarkGuidedFilter(device, params, resolutions) {
  const results = {
    resolutions: {},
    averageTime: 0,
    totalTests: 0
  };
  
      for (const [width, height] of resolutions) {
      // 创建测试纹理
      const { texture: testTexture } = createTestTexture(device, width, height);
      
      const startTime = performance.now();
      await executeGuidedFilter(device, testTexture, params, width, height);
      const endTime = performance.now();
    
    const time = endTime - startTime;
    results.resolutions[`${width}x${height}`] = time;
    results.averageTime += time;
    results.totalTests++;
  }
  
  results.averageTime /= results.totalTests;
  return results;
}

/**
 * 创建测试纹理
 * @param {GPUDevice} device - WebGPU设备
 * @param {number} width - 宽度
 * @param {number} height - 高度
 * @returns {{texture: GPUTexture, width: number, height: number}} 测试纹理和尺寸
 */
function createTestTexture(device, width, height) {
  // 创建测试图像数据
  const floatData = new Float32Array(width * height * 4);
  
  // 生成测试图案
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const index = (y * width + x) * 4;
      
      // 创建边缘测试图案
      const edge = Math.sin(x * 0.1) * Math.cos(y * 0.1);
      const noise = Math.random() * 0.1;
      
      floatData[index] = (edge + noise);     // R
      floatData[index + 1] = (edge + noise); // G
      floatData[index + 2] = (edge + noise); // B
      floatData[index + 3] = 1.0;            // A
    }
  }
  
  // 创建纹理
  const texture = device.createTexture({
    size: { width, height },
    format: 'rgba32float',
    usage: GPUTextureUsage.TEXTURE_BINDING | GPUTextureUsage.COPY_DST,
    label: 'Test Texture'
  });
  
  // 上传数据
  device.queue.writeTexture(
    { texture },
    floatData,
    { bytesPerRow: width * 16 }, // rgba32float每像素16字节
    { width, height }
  );
  
  return { texture, width, height };
} 